package com.kissene3.gui.interfaces;

import org.jetbrains.annotations.*;

import java.awt.event.*;

/** Interface that must be implemented by components that handle mouse hover events. */
@SuppressWarnings("unused")
public interface Hoverable {
	
	/**
	 * The method called while the mouse hovers the component.
	 * @param e The {@link MouseEvent} generated by the movement.
	 */
	void onHover(@NotNull MouseEvent e);
	
	/**
	 * The method called when the mouse enters the component.
	 * @param e The {@link MouseEvent} generated by the movement.
	 */
	void onEnter(@NotNull MouseEvent e);
	
	/**
	 * The method called when the mouse exits the component.
	 * @param e The {@link MouseEvent} generated by the movement.
	 */
	void onExit(@NotNull MouseEvent e);
	
	/** Gets the hovered state of the component. */
	boolean isHovered();
	
	/** Sets the hovered state of the component. */
	void setHovered(boolean hovered);
}
